remove.example:
// No dice at this table in the arena dimension.
const [table] = kcds.world.Dice.tables();
if (table) {
  kcds.world.SmartObject.remove(table.id, 5);
}

remove.exampleCs:
// No dice at this table in the arena dimension.
var table = Dice.Tables()[0];
if (table)
{
    SmartObject.Remove(table["id"], 5);
}

restore.example:
const { SmartObject } = kcds.world;

for (const station of SmartObject.removed(5)) {
  SmartObject.restore(station.id, 5);
}

spawn.example:
const guildBench = kcds.world.SmartObject.spawn({
  blueprint: 'Bench/bench_2places_low',
  position: [1650.5, 2160, 35.4],
  rotation: [0, 0, 0.7071, 0.7071],
  name: 'guild bench',
});
console.info(`${guildBench.kind} ${guildBench.id}`);

getById.example:
const { SmartObject } = kcds.world;

const bed = SmartObject.spawn({ blueprint: 'Bed/bed_low', position: [10, 20, 30] });
console.info(SmartObject.getById(bed.id) === bed);

kind.exampleCs:
var beds = 0;
foreach (var item in SmartObject.All())
{
    if (item.Kind == "bed")
    {
        beds += 1;
    }
}
Log.Info($"{beds} beds");
